package dev.wildcraft.test;
import dev.wildcraft.client.animation.rig.*;
import dev.wildcraft.client.input.*;
import dev.wildcraft.combat.*;
import dev.wildcraft.network.*;
import java.util.*;
import net.fabricmc.fabric.api.client.gametest.v1.*;
import net.fabricmc.fabric.api.client.gametest.v1.context.*;
import net.minecraft.client.*;
import net.minecraft.client.renderer.entity.state.AvatarRenderState;
import net.minecraft.client.resources.DefaultPlayerSkin;
import net.minecraft.core.BlockPos;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.player.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.Vec3;
/** Actual use keys and native arrow settlement, independent runtime-source and native-item observations. */
public final class GroundBowRigClientTest implements FabricClientGameTest {
    static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    static AvatarRenderState state(Minecraft c){return (AvatarRenderState)c.getEntityRenderDispatcher().getRenderer(c.player).createRenderState(c.player,1);}
    static CombatRigLayer.Frame frame(Minecraft c){return state(c).getData(CombatRigLayer.FRAME);}
    static PlayerSkin skin(PlayerModelType t){for(int i=0;i<100;i++){var s=DefaultPlayerSkin.get(new UUID(0,i));if(s.model()==t)return s;}throw new AssertionError("Skin fixture");}
    static void prepare(ClientGameTestContext c,TestSingleplayerContext w,PlayerModelType type,InteractionHand hand){
        c.getInput().releaseKey(v->v.keyUse);c.getInput().releaseKey(v->v.keyUp);c.waitTicks(12);
        w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();p.stopUsingItem();MeleeActions.receive(p,new MeleeIntent(MeleeIntent.CANCEL,(byte)0));p.teleportTo(p.level(),.5,120,.5,Set.of(),0,0,true);p.setDeltaMovement(Vec3.ZERO);p.setHealth(20);p.setInvulnerableTime(0);p.setMainArm(hand==InteractionHand.MAIN_HAND?HumanoidArm.LEFT:HumanoidArm.RIGHT);p.getInventory().clearContent();p.getInventory().setSelectedSlot(0);for(var slot:new EquipmentSlot[]{EquipmentSlot.HEAD,EquipmentSlot.CHEST,EquipmentSlot.LEGS,EquipmentSlot.FEET})p.setItemSlot(slot,ItemStack.EMPTY);var bow=new ItemStack(Items.BOW);bow.set(net.minecraft.core.component.DataComponents.ENCHANTMENT_GLINT_OVERRIDE,true);p.setItemInHand(hand,bow);p.getInventory().setItem(10,new ItemStack(Items.ARROW,32));p.inventoryMenu.broadcastChanges();});
        c.getInput().pressKey(v->v.keyHotbarSlots[0]);c.waitFor(v->v.player.onGround()&&v.player.position().distanceTo(new Vec3(.5,120,.5))<.1&&v.player.getMainArm()==(hand==InteractionHand.MAIN_HAND?HumanoidArm.LEFT:HumanoidArm.RIGHT)&&v.player.getItemInHand(hand).is(Items.BOW));
        c.runOnClient(v->{v.player.setYRot(0);v.player.setXRot(0);RigAudit.fixture=skin(type);RigAudit.begin();GroundBowAudit.begin();});c.waitTicks(8);
    }
    private static void start(ClientGameTestContext c){c.getInput().holdKey(v->v.keyUse);c.waitFor(v->v.player.isUsingItem());c.waitFor(v->frame(v)!=null&&frame(v).clip().equals("bow_ground_hold_empty_L")&&frame(v).weight()>.999);}
    private static void noGround(ClientGameTestContext c,String reason){check(c.computeOnClient(v->frame(v)==null||!frame(v).clip().startsWith("bow_ground_")),reason);}
    @Override public void runTest(ClientGameTestContext c){try(TestSingleplayerContext w=c.worldBuilder().create()){
        w.getConnection().waitForChunksRender();w.getServer().runCommand("gamemode survival @p");w.getServer().runCommand("time set day");w.getServer().runOnServer(s->{for(int x=-8;x<=8;x++)for(int z=-8;z<=8;z++)s.overworld().setBlockAndUpdate(new BlockPos(x,119,z),Blocks.STONE.defaultBlockState());s.getPlayerList().getPlayers().getFirst().teleportTo(.5,120,.5);});c.waitFor(v->v.player.getY()>119);c.getInput().resizeWindow(1280,960);c.runOnClient(v->{v.options.guiScale().set(2);v.options.setCameraType(CameraType.THIRD_PERSON_FRONT);});c.waitFor(v->ActionInput.tickFrame().gameplay());
        for(var type:PlayerModelType.values())for(var hand:InteractionHand.values()){
            prepare(c,w,type,hand);c.runOnClient(v->GroundBowAudit.expectActive=true);c.getInput().holdKey(v->v.keyUse);c.waitFor(v->v.player.isUsingItem()&&v.player.getUsedItemHand()==hand);c.waitFor(v->frame(v)!=null&&frame(v).clip().equals("bow_ground_draw_empty_L")&&frame(v).weight()>.999);c.takeScreenshot("ground-bow-real-draw-"+type+"-"+hand);c.waitFor(v->frame(v)!=null&&frame(v).clip().equals("bow_ground_hold_empty_L")&&RigAudit.hands>0);c.takeScreenshot("ground-bow-real-hold-"+type+"-"+hand);c.runOnClient(v->v.options.setCameraType(CameraType.THIRD_PERSON_BACK));c.takeScreenshot("ground-bow-real-hold-back-"+type+"-"+hand);c.runOnClient(v->v.options.setCameraType(CameraType.THIRD_PERSON_FRONT));
            c.runOnClient(v->{check(GroundBowAudit.stages.equals(Set.of(0,1,2))&&GroundBowAudit.firstHold==20&&GroundBowAudit.frames>0&&GroundBowAudit.draws>0&&GroundBowAudit.holds>0,"Actual ground draw/hold body GPU");check(RigAudit.texture.equals(RigAudit.fixture.body().texturePath().toString()),"Actual native skin GPU");System.out.println("C6P ACTUAL "+type+" "+hand+" frames="+GroundBowAudit.frames+" pull="+GroundBowAudit.stages+" maxStringGap="+GroundBowAudit.maxStringGap);});
            c.runOnClient(v->GroundBowAudit.expectActive=false);c.getInput().releaseKey(v->v.keyUse);c.waitFor(v->!v.player.isUsingItem()&&v.player.getItemInHand(hand).getDamageValue()==1);check(c.computeOnClient(v->frame(v)==null||!frame(v).clip().startsWith("bow_ground_")),"Stopped actual use immediately gives hands back");w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();check(GroundBowAudit.shots.get()==1&&p.getInventory().getItem(10).getCount()==31&&p.getItemInHand(hand).getDamageValue()==1,"One native arrow/ammo/wear only");});c.takeScreenshot("ground-bow-after-real-release-"+type+"-"+hand);
        }
        prepare(c,w,PlayerModelType.SLIM,InteractionHand.OFF_HAND);c.runOnClient(v->{v.options.framerateLimit().set(10);GroundBowAudit.expectActive=true;});c.getInput().holdKey(v->v.keyUse);c.waitFor(v->v.player.isUsingItem());c.waitFor(v->frame(v)!=null&&frame(v).clip().equals("bow_ground_hold_empty_L")&&frame(v).weight()>.999);c.takeScreenshot("ground-bow-real-10fps-pull");c.runOnClient(v->{check(GroundBowAudit.draws>0&&GroundBowAudit.holds>0,"Actual low-FPS draw/hold");GroundBowAudit.expectActive=false;v.options.framerateLimit().set(120);});c.getInput().releaseKey(v->v.keyUse);c.waitTicks(2);
        prepare(c,w,PlayerModelType.WIDE,InteractionHand.MAIN_HAND);start(c);c.getInput().holdKey(v->v.keyJump);c.waitFor(v->!v.player.onGround());c.getInput().releaseKey(v->v.keyJump);noGround(c,"Actual jump retains original air-bow path");c.takeScreenshot("ground-bow-native-jump-air");c.getInput().releaseKey(v->v.keyUse);
        prepare(c,w,PlayerModelType.WIDE,InteractionHand.MAIN_HAND);start(c);c.runOnClient(v->{v.player.setXRot(18);v.player.setYRot(25);});c.waitTicks(2);check(c.computeOnClient(v->frame(v)!=null),"Independent real native look keeps ground bow qualified");c.takeScreenshot("ground-bow-native-independent-look");c.runOnClient(v->{check(v.player.getXRot()==18&&v.player.getYRot()==25,"Rig does not alter camera/player aim");v.player.setYRot(90);v.player.setXRot(0);});c.waitTicks(2);c.takeScreenshot("ground-bow-real-side-string-contact");
        c.setScreen(()->new net.minecraft.client.gui.screens.PauseScreen(true));c.waitFor(v->v.isPaused());boolean pausedUse=c.computeOnClient(v->v.player.isUsingItem());System.out.println("C6P PAUSE nativeUsing="+pausedUse+" frame="+c.computeOnClient(v->frame(v)==null?"native":frame(v).clip()));if(pausedUse){float paused=c.computeOnClient(v->frame(v).time());c.waitTicks(12);check(c.computeOnClient(v->frame(v)!=null&&Math.abs(frame(v).time()-paused)<.000001),"Actual pause freezes held source clock");}else{c.waitTicks(12);noGround(c,"Native pause transition ended actual use; do not retain a fake source bow hold");}c.takeScreenshot("ground-bow-paused-clock");c.setScreen(()->null);c.getInput().releaseKey(v->v.keyUse);c.waitTicks(2);
        prepare(c,w,PlayerModelType.WIDE,InteractionHand.MAIN_HAND);start(c);c.setScreen(()->new net.minecraft.client.gui.screens.inventory.InventoryScreen(Minecraft.getInstance().player));noGround(c,"Actual inventory GUI takes hands immediately");c.takeScreenshot("ground-bow-real-inventory-exit");c.setScreen(()->null);c.getInput().releaseKey(v->v.keyUse);
        prepare(c,w,PlayerModelType.WIDE,InteractionHand.MAIN_HAND);start(c);c.getInput().holdKey(v->v.keyUp);c.waitTicks(4);noGround(c,"Actual walking uses original moving bow");c.takeScreenshot("ground-bow-real-motion-exit");c.getInput().releaseKey(v->v.keyUp);c.getInput().releaseKey(v->v.keyUse);
        prepare(c,w,PlayerModelType.WIDE,InteractionHand.MAIN_HAND);start(c);w.getServer().runOnServer(v->{var p=v.getPlayerList().getPlayers().getFirst();p.setItemSlot(EquipmentSlot.CHEST,new ItemStack(Items.IRON_CHESTPLATE));p.inventoryMenu.broadcastChanges();});c.waitFor(v->v.player.getItemBySlot(EquipmentSlot.CHEST).is(Items.IRON_CHESTPLATE));noGround(c,"Actual armor keeps prior native body");c.takeScreenshot("ground-bow-real-armor-exit");c.getInput().releaseKey(v->v.keyUse);
        prepare(c,w,PlayerModelType.WIDE,InteractionHand.MAIN_HAND);start(c);w.getServer().runOnServer(v->{var p=v.getPlayerList().getPlayers().getFirst();p.hurtServer(v.overworld(),p.damageSources().generic(),1);check(p.getHealth()<20,"Bow source adds no immunity");});c.waitFor(v->v.player.getHealth()<20&&MeleeActions.view(v.player).hurt()>0);noGround(c,"Actual damage immediately owns body");c.takeScreenshot("ground-bow-real-hurt-exit");c.getInput().releaseKey(v->v.keyUse);
        prepare(c,w,PlayerModelType.WIDE,InteractionHand.OFF_HAND);start(c);w.getServer().runOnServer(v->{var p=v.getPlayerList().getPlayers().getFirst();p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.TORCH));p.inventoryMenu.broadcastChanges();});c.waitFor(v->v.player.getMainHandItem().is(Items.TORCH));noGround(c,"Other real occupied hand cannot be borrowed by drawing source");c.takeScreenshot("ground-bow-real-other-hand-torch");c.getInput().releaseKey(v->v.keyUse);
        prepare(c,w,PlayerModelType.WIDE,InteractionHand.MAIN_HAND);w.getServer().runOnServer(v->{var p=v.getPlayerList().getPlayers().getFirst();p.getInventory().setItem(1,new ItemStack(Items.TORCH));p.inventoryMenu.broadcastChanges();});start(c);c.getInput().pressKey(v->v.keyHotbarSlots[1]);c.waitFor(v->v.player.getInventory().getSelectedSlot()==1&&v.player.getMainHandItem().is(Items.TORCH));noGround(c,"Real selected inventory item owns hands");c.takeScreenshot("ground-bow-real-selected-torch");c.getInput().releaseKey(v->v.keyUse);c.waitTicks(3);w.getServer().runOnServer(v->{var p=v.getPlayerList().getPlayers().getFirst();check(p.getInventory().getItem(10).getCount()==32&&p.getInventory().getItem(0).getDamageValue()==0&&GroundBowAudit.shots.get()==0,"Native slot cancellation produces no shot/ammo/wear");});
        var nativeReplacementResults=new ArrayList<String>();
        for(boolean nativeOnly:new boolean[]{false,true}){
            prepare(c,w,PlayerModelType.WIDE,InteractionHand.MAIN_HAND);
            if(nativeOnly){w.getServer().runOnServer(v->{var p=v.getPlayerList().getPlayers().getFirst();p.setItemSlot(EquipmentSlot.CHEST,new ItemStack(Items.IRON_CHESTPLATE));p.inventoryMenu.broadcastChanges();});c.waitFor(v->v.player.getItemBySlot(EquipmentSlot.CHEST).is(Items.IRON_CHESTPLATE));c.getInput().holdKey(v->v.keyUse);c.waitFor(v->v.player.isUsingItem()&&v.player.getTicksUsingItem()>=20);}else start(c);
            w.getServer().runOnServer(v->{var p=v.getPlayerList().getPlayers().getFirst();var replacement=new ItemStack(Items.BOW);replacement.set(net.minecraft.core.component.DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal("Actual replacement bow"));p.setItemInHand(InteractionHand.MAIN_HAND,replacement);p.inventoryMenu.broadcastChanges();});c.waitFor(v->v.player.getMainHandItem().has(net.minecraft.core.component.DataComponents.CUSTOM_NAME));
            c.runOnClient(v->{var f=frame(v);if(f!=null&&f.clip().startsWith("bow_ground_"))check(!nativeOnly&&v.player.getUseItem()==v.player.getMainHandItem(),"A new native bow may continue only with its current real use ownership");});
            w.getServer().runOnServer(v->{var p=v.getPlayerList().getPlayers().getFirst();check(GroundBowAudit.shots.get()==0&&p.getInventory().getItem(10).getCount()==32&&p.getMainHandItem().getDamageValue()==0,"Replacement visuals create no shot/wear/ammo before real release");System.out.println("C6P REPLACE BEFORE source="+!nativeOnly+" using="+p.isUsingItem()+" sameStack="+(p.getUseItem()==p.getMainHandItem())+" ticks="+p.getTicksUsingItem());});
            c.takeScreenshot("ground-bow-real-replacement-"+(nativeOnly?"native-armor-baseline":"source-owner"));c.getInput().releaseKey(v->v.keyUse);c.waitTicks(3);
            w.getServer().runOnServer(v->{var p=v.getPlayerList().getPlayers().getFirst();String result=GroundBowAudit.shots.get()+":"+p.getInventory().getItem(10).getCount()+":"+p.getMainHandItem().getDamageValue();nativeReplacementResults.add(result);System.out.println("C6P REPLACE AFTER source="+!nativeOnly+" settlement="+result);check(result.equals("1:31:1"),"Actual native same-type replacement transfers use and releases exactly one real arrow/wear");});
        }
        check(nativeReplacementResults.size()==2&&nativeReplacementResults.getFirst().equals(nativeReplacementResults.getLast()),"Source bow replacement preserves the real native fallback settlement");
        prepare(c,w,PlayerModelType.WIDE,InteractionHand.MAIN_HAND);w.getServer().runOnServer(v->{var p=v.getPlayerList().getPlayers().getFirst();p.setMainArm(HumanoidArm.RIGHT);});c.waitFor(v->v.player.getMainArm()==HumanoidArm.RIGHT);c.getInput().holdKey(v->v.keyUse);c.waitFor(v->v.player.isUsingItem());c.waitTicks(20);check(c.computeOnClient(v->frame(v)!=null&&frame(v).clip().equals("bow_ground_hold_empty_R")),"True RIGHT ground bow follows derived qualified source");check(c.computeOnClient(v->v.player.getMainArm()==HumanoidArm.RIGHT),"No forced left-arm setting");c.takeScreenshot("ground-bow-derived-right-use");c.getInput().releaseKey(v->v.keyUse);
        prepare(c,w,PlayerModelType.WIDE,InteractionHand.MAIN_HAND);w.getServer().runOnServer(v->{var p=v.getPlayerList().getPlayers().getFirst();p.getInventory().setItem(10,ItemStack.EMPTY);p.inventoryMenu.broadcastChanges();});c.waitFor(v->v.player.getInventory().getItem(10).isEmpty());c.getInput().holdKey(v->v.keyUse);c.waitTicks(5);noGround(c,"No source without actual native ammo/use");check(c.computeOnClient(v->!v.player.isUsingItem()),"Native empty ammo fails to start use");c.takeScreenshot("ground-bow-native-no-ammo");c.getInput().releaseKey(v->v.keyUse);w.getServer().runOnServer(v->{var p=v.getPlayerList().getPlayers().getFirst();check(p.getMainHandItem().getDamageValue()==0&&GroundBowAudit.shots.get()==0,"No ammo grants no source shot or wear");});
        System.out.println("C6P actual ground LEFT use mainLEFT/off-mainRIGHT, native ticks/draw/hold/real skin-bow/GPU/native three pull sprites/nock/source segment lengths and mask/native head/GPU/one-shot ammo-wear, real 10FPS/air exit/native look/pause/GUI/movement/hurt/armor/other hand/slot cancellation/RIGHT ground source/empty ammo PASS");
    }finally{c.getInput().releaseKey(v->v.keyJump);c.getInput().releaseKey(v->v.keyUse);c.getInput().releaseKey(v->v.keyUp);c.runOnClient(v->{GroundBowAudit.enabled=false;RigAudit.enabled=false;RigAudit.fixture=null;DodgeFeedbackAudit.checkingNativeItem=false;v.options.framerateLimit().set(120);v.options.setCameraType(CameraType.FIRST_PERSON);});}}
}
